"""
"""
from collections import namedtuple, OrderedDict
import logging
import os
import re


from taf.collectors.core import CollectorSetFactory
from taf.collectors.core.entities.managed_admin_connection import ManagedSbtsAdminConnection
from taf.collectors.core.entities.managed_coam_cu_connection import ManagedCoamCUConnection
from taf.collectors.core.entities.managed_vdu_connection import ManagedVduConnection
from taf.internal.managedobject import ManagedObject

from .collector_configuration_data import CollectorConfigurationData
from .config.builders.gnb_builder import ClassicalGnbBuilder, CloudGnbBuilder
from .config.builders.ue_builder import AirphoneBuilder
from .config.builders.director import Director
from .config.info_provider.airphone_information_provider import AirphoneInformationProvider
from .config.info_provider.k8s_information_provider import K8sInformationProvider
from .config.info_provider.oam_information_provider \
    import SbtsOamInformationProvider, VcuOamInformationProvider, VduOamInformationProvider
from .config.info_provider.testline_configuration_information_provider import TestlineConfigurationInformationProvider
from .config.builders.util import split_and_remove_blank_spaces
from .log_file_provider.gnb_log_file_provider_strategy import ClassicalGnbLogFileProviderStrategy, \
    CloudGnbLogFileProviderStrategy
from .log_file_provider.ue_log_file_provider_strategy import AirphoneLogFileProviderStrategy

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class NetworkElement(namedtuple("NetworkElement", "type id")):
    __slots__ = ()

    @property
    def name(self):
        return f"{self.type}_{self.id}"

    @classmethod
    def from_name(cls, name):
        return NetworkElement(*(lambda x: (x[0], int(x[1])))(name.split('_')))


class LogCollection(ManagedObject):

    def __init__(self, tl_config, **kwargs):
        super(LogCollection, self).__init__(**kwargs)
        self._tl_config_information_provider = TestlineConfigurationInformationProvider(tl_config=tl_config)
        self._collector_configuration_data = CollectorConfigurationData()

    def create_collectors_using_testline_information(self, names, configuration, network_elements=None,
                                                     available_collectors=None):
        collector_configurations = self.create_collector_configurations(
            log_names=names,
            log_configurations=configuration,
            network_elements=network_elements)
        logger.debug("Collector configurations: %s", collector_configurations)
        sorted_collector_configurations = self._collector_configuration_data.sorted_collector_configurations
        logger.info("Sorted collector configurations: %s", sorted_collector_configurations)
        logger.debug(
            "Mapping from log type and network element to collector configuration: %s",
            self._collector_configuration_data.mapping)
        collectors = CollectorSetFactory(available_collectors=available_collectors).create(
            configuration=sorted_collector_configurations,
            existing_arguments={})
        return collectors

    def create_collector_configurations(self, log_names, log_configurations, network_elements):
        log_names = split_and_remove_blank_spaces(log_names)
        network_elements = split_and_remove_blank_spaces(network_elements) if network_elements \
            else self._tl_config_information_provider.get_all_network_elements()

        for network_element in map(NetworkElement.from_name, network_elements):
            ne_log_configurations = self._create_ne_log_configurations(
                log_names=log_names,
                log_configurations=log_configurations,
                network_element=network_element)

            builder, director = self._create_builder_and_director(network_element)
            if builder:
                sorted_configs = self._sort_ne_log_configurations(ne_log_configurations)
                builder.setup()
                try:
                    director.construct(sorted_configs)
                finally:
                    builder.teardown()
                self._collector_configuration_data.update(builder.get_result())
        return self._collector_configuration_data.collector_configurations

    @staticmethod
    def _sort_ne_log_configurations(ne_log_configurations):
        sorted_ne_log_configuration = OrderedDict()
        sorted_ne_log_configuration.update(
            {name: config for name, config in ne_log_configurations.items() if config['type'] == 'group'})
        sorted_ne_log_configuration.update(
            {name: config for name, config in ne_log_configurations.items() if config['type'] != 'group'})
        return sorted_ne_log_configuration

    def _create_ne_log_configurations(self, log_names, log_configurations, network_element):
        ne_log_configurations = {}
        for log_name in log_names:
            log_configuration = log_configurations[log_name]
            if log_configuration['type'] == 'group':
                member_ne_log_configurations = self._create_ne_log_configurations(
                    log_names=split_and_remove_blank_spaces(log_configuration['members']),
                    log_configurations=log_configurations,
                    network_element=network_element)
                for key in member_ne_log_configurations:
                    ne_log_configurations[key] = self._get_ne_log_configuration(member_ne_log_configurations[key])
                if member_ne_log_configurations:
                    ne_log_configurations[log_name] = {
                        'type': "group",
                        'members': [
                            f"{member}"
                            for member in member_ne_log_configurations
                            if any(member.startswith(name)
                                   for name in split_and_remove_blank_spaces(log_configuration['members']))]}
            elif re.search(
                    log_configuration.get('scope', ".*"),
                    network_element.name):
                ne_log_configurations[f"{log_name}_{network_element.name}"] = self._get_ne_log_configuration(
                    log_configuration)
        return ne_log_configurations

    @staticmethod
    def _get_ne_log_configuration(log_configuration):
        result = log_configuration.copy()
        result.pop("scope", None)
        return result

    def _create_builder_and_director(self, network_element):

        if network_element.type == 'gnb':
            builder = self._create_gnb_builder(network_element)
        elif network_element.type == 'ue':
            builder = self._create_ue_builder(network_element)
        else:
            raise AssertionError(
                f"unsupported network element type {network_element.type!r} for NE {network_element.id!r}")
        return builder, Director(builder=builder)

    def _create_gnb_builder(self, network_element):
        deployment_type = self._tl_config_information_provider.get_deployment_type(node_id=network_element.id)
        if deployment_type == "classical":
            builder = self._create_classical_gnb_builder(network_element)
        elif deployment_type == "cloud":
            builder = self._create_cloud_gnb_builder(network_element)
        else:
            raise AssertionError(f"unsupported deployment type {deployment_type!r} for gNB {network_element.id!r}")
        return builder

    def _create_cloud_gnb_builder(self, network_element):
        vcu_oam_information_provider = VcuOamInformationProvider(
            managed_oam_connection=ManagedCoamCUConnection(
                cu_connection_params=self._tl_config_information_provider.get_cu_oam_http_connection_details(
                    node_id=network_element.id)))
        vdu_oam_information_providers = [
            VduOamInformationProvider(
                managed_oam_connection=ManagedVduConnection(
                    vdu_connection_params=self._tl_config_information_provider.get_vdu_oam_http_connection_details(
                        node_id=network_element.id,
                        vdu_id=vdu_id)))
            for vdu_id in self._tl_config_information_provider.get_du_ids(node_id=network_element.id)]
        builder = CloudGnbBuilder(
            tl_config_information_provider=self._tl_config_information_provider,
            k8s_information_provider=K8sInformationProvider(
                tl_config_information_provider=self._tl_config_information_provider),
            vcu_oam_information_provider=vcu_oam_information_provider,
            vdu_oam_information_providers=vdu_oam_information_providers,
            ne_id=network_element.id)
        return builder

    def _create_classical_gnb_builder(self, network_element):
        managed_sbts_oam_admin_connection = ManagedSbtsAdminConnection(
            admin_connection_params=self._tl_config_information_provider.get_web_service(
                node_id=network_element.id))
        sbts_oam_information_provider = SbtsOamInformationProvider(
            managed_oam_connection=managed_sbts_oam_admin_connection)
        builder = ClassicalGnbBuilder(
            tl_config_information_provider=self._tl_config_information_provider,
            sbts_oam_information_provider=sbts_oam_information_provider,
            ne_id=network_element.id)
        return builder

    def _create_ue_builder(self, network_element):
        ue_type = self._tl_config_information_provider.get_ue_type(node_id=network_element.id)
        if ue_type == "airphone":
            builder = AirphoneBuilder(
                tl_config_information_provider=self._tl_config_information_provider,
                airphone_information_provider=AirphoneInformationProvider(
                    tl_config_information_provider=self._tl_config_information_provider),
                ne_id=network_element.id)
        else:
            raise AssertionError(f"unsupported UE type {ue_type!r} for UE {network_element.id!r}")
        return builder

    def get_log_file(self, log_type, network_element, target_dir):
        """
        Determine a concrete log file from one trace, defined by its log_name and network_element.

        :param str log_type: The collector type, i.e. BIP, TTI, Syslog, Emil
        :param str network_element: The network element the data was collected on, i.e. gnb_0
        :param str target_dir: The target directory, that was used in "collect collectors"
        """
        log_type = log_type.lower()

        log_file_provider_strategy = self._get_log_file_provider_strategy(log_type, network_element)

        collector_config = self._collector_configuration_data.get_configuration_by_log_type_and_network_element(
            log_type,
            network_element)
        if not collector_config:
            logger.warning("No fitting collector found in get_log_file!")
            logger.warning(collector_config)
            return
        log_directory = self._get_log_file_path(collector_config['name'], target_dir)

        if not os.path.exists(log_directory):
            raise AssertionError(
                f"Error: In get_log_file the expected path does not exist. ({log_directory}). "
                "Assure that you use the same target_dir as in collect collectors!")

        return getattr(log_file_provider_strategy, f"get_{log_type}_log_file")(log_directory, collector_config)

    def _get_log_file_provider_strategy(self, log_type, network_element):
        network_element = NetworkElement.from_name(network_element)
        if network_element.type == 'gnb':
            deployment_type = self._tl_config_information_provider.get_deployment_type(node_id=network_element.id)
            if deployment_type == "classical":
                return ClassicalGnbLogFileProviderStrategy(
                    collector_configuration_data=self._collector_configuration_data)
            elif deployment_type == "cloud":
                return CloudGnbLogFileProviderStrategy(
                    collector_configuration_data=self._collector_configuration_data)
        elif network_element.type == 'ue':
            if self._tl_config_information_provider.get_ue_type(node_id=network_element.id):
                return AirphoneLogFileProviderStrategy(
                    collector_configuration_data=self._collector_configuration_data)

    def _get_log_file_path(self, collector_name, target_dir):
        """
        Determine the full path to the current log files for the log type.

        :param str collector_name: The name of the collector in the collector_configuration structure
        :param str target_dir: The path to the collected logs, like it was provided to collect collectors
        """
        logger.info(f"Collector configuration: {self._collector_configuration_data.collector_configurations}")
        parents = self._collector_configuration_data.find_ancestor_group_names(collector_name)
        logger.info(f"Parents: {parents}")
        return os.path.join(target_dir, *parents, collector_name)

    def load(self, stream):
        self._collector_configuration_data.load(stream)

    def dump(self, stream):
        self._collector_configuration_data.dump(stream)
